/** [sql-output.xml] OutputMapper.getOutputRequestSearch **/ SELECT MF13_COMPANY , MF13_FACTORY , MF13_NO , MF13_DAT , MF13_DAT_TIME , MF13_LINE_CODE , LINE_NM AS MF13_LINE_NM , MF13_COMP_GBN FROM TB_MF_13 mf13 LEFT JOIN DNKR_LINE_CODE line on mf13.MF13_COMPANY = line.COMPANY AND mf13.MF13_FACTORY = line.FACTORY AND mf13.MF13_LINE_CODE = line.LINE_CODE LEFT JOIN TB_ST_03 st03 on mf13.MF13_COMPANY = st03.ST03_COMPANY AND mf13.MF13_FACTORY = st03.ST03_FACTORY AND mf13.MF13_NO = st03.ST03_OUTPUT_NO WHERE MF13_COMPANY = #{company} AND MF13_FACTORY = #{factory}
AND MF13_NO = #{mf13No}
AND MF13_COMP_GBN = 'N' AND ST03_OUTPUT_NO IS NULL ORDER BY MF13_DAT DESC, MF13_NO DESC

/** [sql-output.xml] OutputMapper.getOutputHistorySearchInfo **/
SELECT *
FROM TB_ST_03
WHERE ST03_COMPANY = #{company}
  AND ST03_FACTORY = #{factory}
  AND ST03_OUTPUT_NO = #{st03OutputNo}

/** [sql-output.xml] OutputMapper.inspectChk **/
SELECT *
FROM TB_QA_07
WHERE QA07_COMPANY = #{company}
  AND QA07_FACTORY = #{factory}
  AND QA07_CODE = #{st03Code}
  AND QA07_LOT = #{st03Lot}
  AND QA07_LOT_SEQ = #{st03LotSeq}

/** [sql-output.xml] OutputMapper.inspectSpecChk **/
SELECT QA08_STATUS
FROM TB_QA_07 QA07
LEFT JOIN TB_QA_08 QA08 ON QA07.QA07_COMPANY = QA08.QA08_COMPANY AND QA07.QA07_FACTORY = QA08.QA08_FACTORY AND QA07.QA07_CODE = QA08.QA08_CODE AND QA07.QA07_NO = QA08.QA07_NO
WHERE QA07_COMPANY = #{company}
  AND QA07_FACTORY = #{factory}
  AND QA07_CODE = #{st03Code}
  AND QA07_LOT_SEQ = #{st03LotSeq}

mapper.insert:
	/** [sql-output.xml] OutputMapper.insertOfOutputHistory **/

        SELECT COALESCE(MAX(ST03_SEQ)+1,1) AS ST03_SEQ
        FROM TB_ST_03
        WHERE ST03_COMPANY = #{company}
          AND ST03_FACTORY = #{factory}
          AND TO_CHAR(ST03_DAT, 'YYYY-MM-DD') = #{st03Dat}


    INSERT INTO TB_ST_03 (
        ST03_COMPANY
        , ST03_FACTORY
        , ST03_NO
        , ST03_DAT
        , ST03_CUS
        , ST03_SEQ
        , ST03_CODE
        , ST03_LOT
        , ST03_GBN
        , ST03_UNT
        , ST03_QTY
        , ST03_MOQ
        , ST03_RMK
        , ST03_STOK
        , ST03_DIST
        , ST03_INDTE
        , ST03_EMPNO
        , ST03_DGBN
        , ST03_QR
        , ST03_OUTPUT_NO
        , ST03_OUTPUT_DTL_NO
        , ST03_PCC
        , ST03_RENO
        , ST03_RTNO
        , ST03_LINE
        , ST03_LOT_SEQ
        , ST03_MST_NO
    ) VALUES (
        #{company}
        , #{factory}
        , CONCAT(TO_CHAR(SYSDATE, 'YYYYMMDD'), LPAD(#{st03Seq}, 5, '0'))
        , TO_DATE(TO_CHAR(SYSDATE, 'YYYY-MM-DD'), 'YYYY-MM-DD')
        , #{st03Cus}
        , #{st03Seq}
        , #{cm08Code}
        , CASE WHEN #{st03Lot} = '' THEN CONCAT(REPLACE(#{st03Dat},'-',''), LPAD(#{st03Seq},5,'0'))
        ELSE #{st03Lot} END
        , #{st03Gbn}
        , #{st03Unt}
        , #{st03Qty}
        , #{st03Moq}
        , #{st03Rmk}
        , #{st03Stok}
        , #{st03Dist}
        , sysdate
        , #{st03Empno}
        , #{st03Dgbn}
        , #{st03Qr}
        , #{st03OutputNo}
        , CASE WHEN #{st03OutputDtlNo} IS NULL THEN CONCAT(#{st03OutputNo}, LPAD(#{st03Seq},5,'0'))
          ELSE #{st03OutputDtlNo} END
        , #{st03Pcc}
        , #{st03Reno}
        , #{st03Rtno}
        , #{st03Line}
        , #{st03LotSeq}
        , #{st03OutputNo}
    )

mapper.update:
    	/** [sql-output.xml] OutputMapper.updateOfPdStock **/
		UPDATE tb_st_01
		 -- 재고수량을 변경하는 경우
		   SET st01_qty = st01_qty - #{outQty} + #{ipQty}

		 -- 재고 차감 (출고등록/입고삭제)
		   SET st01_qty =  st01_qty - #{outQty}

		 -- 재고 증가 (입고등록/출고삭제)
		   SET st01_qty =  st01_qty + #{ipQty}

		 -- 재고실사 품목일때 기존의 수량 0
		   SET st01_qty = '0'

		WHERE 1=1
		AND st01_company = #{company}
		AND st01_factory = #{factory}
		AND st01_code = #{code}
		AND st01_stok = #{stock}

		   AND st01_lot = #{lot}
		   AND st01_lot_seq = #{lotSeq}

